import { createClient } from 'supabase';
import Papa from 'papaparse';
Deno.serve(async()=>{
 const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');const key=keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;const sb=createClient(Deno.env.get('SUPABASE_URL')!,key,{auth:{persistSession:false}});
 try{
  const r=await fetch('https://raw.githubusercontent.com/olbauday/FPL-Core-Insights/main/data/2026-2027/teams.csv',{cache:'no-store'});if(!r.ok)throw new Error(`teams ${r.status}`);const text=await r.text();const rows=Papa.parse(text,{header:true,skipEmptyLines:true,transformHeader:(h:string)=>h.trim().replace(/^\uFEFF/,'')}).data as any[];
  const first=rows[0]||{};const eloKey=Object.keys(first).find(k=>k.trim().toLowerCase()==='elo')||'elo';const payload=rows.map(t=>({fpl_team_id:Number(t.id),team_code:Number(t.code),elo:t[eloKey]===undefined||t[eloKey]===''?null:Number(t[eloKey])}));
  for(const x of payload){const {error}=await sb.from('teams').update({team_code:x.team_code,elo:x.elo,updated_at:new Date().toISOString()}).eq('fpl_team_id',x.fpl_team_id);if(error)throw error;}
  return Response.json({ok:true,count:payload.length,keys:Object.keys(first),elo_key:eloKey,first:payload[0],last:payload[payload.length-1]});
 }catch(e){return Response.json({ok:false,error:e instanceof Error?e.message:String(e)},{status:500})}
});
